user_prompt:
method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0
    ensures |result| == |numbers|
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i+1])
{
    var maxSoFar := numbers[0];
    var n := |numbers|;
    result := new int[n];

    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant |result| == n
        invariant forall j :: 0 <= j < i ==> result[j] == Max(numbers[0..j+1])
    {
        maxSoFar := if maxSoFar < numbers[i] then numbers[i] else maxSoFar;
        result[i] := maxSoFar;
        i := i + 1;
    }
}

problem_data.canonical_solution:
running_max = None
result = []

for n in numbers:
    if running_max is None:
        running_max = n
    else:
        running_max = max(running_max, n)

    result.append(running_max)

return result

